export type Cell = [number, number];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(key));
  const countLivingNeighbors = (cell: Cell): number =>
    neighborsOf(cell).filter((neighbor) => living.has(key(neighbor))).length;

  const survivors = cells.filter((cell) => countLivingNeighbors(cell) === 3);
  const births = cells
    .flatMap(neighborsOf)
    .filter((cell) => !living.has(key(cell)) && countLivingNeighbors(cell) === 3);

  return [...survivors, ...births];
}

